const items = $input.all();
const results = [];

for (const item of items) {
  const html = (item.json.data || item.json.body || '').toString();

  // Remove script/style tags and HTML markup
  let text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();

  // Extract title from HTML
  const titleMatch = html.match(/<title[^>]*>(.*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : 'Untitled';

  // Extract headings for structure
  const headings = [];
  const headingRegex = /<h[1-3][^>]*>(.*?)<\/h[1-3]>/gi;
  let match;
  while ((match = headingRegex.exec(html)) !== null) {
    headings.push(match[1].replace(/<[^>]*>/g, '').trim());
  }

  results.push({
    json: {
      url: item.json.url || '',
      title,
      content: text.substring(0, 5000),
      headings: headings.slice(0, 20),
      charCount: text.length,
      scrapedAt: new Date().toISOString()
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const content = item.json.content || '';
  const headings = item.json.headings || [];

  // Extract key sentences (first sentences of paragraphs)
  const sentences = content.split(/[.!?]+/).filter(s => s.trim().length > 30).slice(0, 10);

  // Extract potential keywords (frequent capitalized words)
  const words = content.match(/[A-Z][a-z]{3,}/g) || [];
  const wordFreq = {};
  words.forEach(w => { wordFreq[w] = (wordFreq[w] || 0) + 1; });
  const keywords = Object.entries(wordFreq).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([w]) => w);

  results.push({
    json: {
      url: item.json.url,
      title: item.json.title,
      keySentences: sentences.map(s => s.trim()).join('. '),
      headings: headings.join('; '),
      keywords: keywords.join(', '),
      charCount: item.json.charCount,
      scrapedAt: item.json.scrapedAt
    }
  });
}

return results;
